<template><div class="page"><div class="head"><div><span>FAULT TREE ANALYSIS</span><h2>FTA 图形化故障树</h2><p>维护顶事件、逻辑门、基础事件以及父子连线，保存时自动校验循环引用。</p></div><div><el-button @click="autoLayout">自动布局</el-button><el-button type="primary" @click="save">保存故障树</el-button></div></div><div class="layout"><el-card shadow="never" class="editor"><template #header><div class="title"><b>节点与关系</b><el-tag>版本 {{version}}</el-tag></div></template><el-form label-position="top"><el-form-item label="故障树名称"><el-input v-model="treeName"/></el-form-item></el-form><div class="buttons"><el-button v-for="x in types" :key="x.value" size="small" @click="add(x.value)">+ {{x.label}}</el-button></div><el-table :data="nodes" size="small" max-height="320"><el-table-column label="名称" min-width="150"><template #default="s"><el-input v-model="s.row.name"/></template></el-table-column><el-table-column label="类型" width="110"><template #default="s"><el-select v-model="s.row.type"><el-option v-for="x in types" :key="x.value" :label="x.label" :value="x.value"/></el-select></template></el-table-column><el-table-column width="65"><template #default="s"><el-button link type="danger" @click="removeNode(s.row.id)">删除</el-button></template></el-table-column></el-table><h3>新增连线</h3><div class="edge-add"><el-select v-model="edgeForm.source" placeholder="父节点"><el-option v-for="n in nodes" :key="n.id" :label="n.name" :value="n.id"/></el-select><span>→</span><el-select v-model="edgeForm.target" placeholder="子节点"><el-option v-for="n in nodes" :key="n.id" :label="n.name" :value="n.id"/></el-select><el-button type="primary" plain @click="addEdge">连接</el-button></div><el-table :data="edges" size="small" max-height="210"><el-table-column label="父节点"><template #default="s">{{nodeName(s.row.source)}}</template></el-table-column><el-table-column label="子节点"><template #default="s">{{nodeName(s.row.target)}}</template></el-table-column><el-table-column width="65"><template #default="s"><el-button link type="danger" @click="edges.splice(s.$index,1)">删除</el-button></template></el-table-column></el-table></el-card><el-card shadow="never" class="canvas-card"><template #header><div class="title"><b>故障逻辑图</b><span>拖动节点可调整位置</span></div></template><div ref="canvas" class="canvas"><svg :viewBox="`0 0 ${canvasWidth} ${canvasHeight}`"><defs><marker id="arrow" markerWidth="9" markerHeight="7" refX="8" refY="3.5" orient="auto"><polygon points="0 0, 9 3.5, 0 7" fill="#7b8ca4"/></marker></defs><line v-for="(e,i) in edgeLines" :key="i" :x1="e.x1" :y1="e.y1" :x2="e.x2" :y2="e.y2" stroke="#7b8ca4" stroke-width="2" marker-end="url(#arrow)"/></svg><div v-for="n in nodes" :key="n.id" :class="['node',n.type]" :style="{left:n.x+'px',top:n.y+'px'}" @pointerdown="startDrag($event,n)"><span v-if="n.type==='AND'||n.type==='OR'" class="gate">{{n.type}}</span><span v-else>{{n.name}}</span><small v-if="n.type!=='AND'&&n.type!=='OR'">{{typeName(n.type)}}</small></div><el-empty v-if="!nodes.length" description="请添加故障树节点"/></div></el-card></div></div></template>
<script setup>import{ref,computed,onMounted,onUnmounted}from'vue';import{ElMessage}from'element-plus';const types=[{label:'顶事件',value:'top'},{label:'中间事件',value:'event'},{label:'基础事件',value:'basic'},{label:'AND门',value:'AND'},{label:'OR门',value:'OR'}],treeId=ref(),treeName=ref('默认故障树'),version=ref(1),nodes=ref([]),edges=ref([]),edgeForm=ref({source:'',target:''}),canvas=ref(),canvasWidth=900,canvasHeight=650;const typeName=t=>types.find(x=>x.value===t)?.label||t,nodeName=id=>nodes.value.find(x=>String(x.id)===String(id))?.name||id;const edgeLines=computed(()=>edges.value.map(e=>{const a=nodes.value.find(n=>String(n.id)===String(e.source)),b=nodes.value.find(n=>String(n.id)===String(e.target));return a&&b?{x1:a.x+70,y1:a.y+58,x2:b.x+70,y2:b.y}:null}).filter(Boolean));function add(type){const id=`n-${Date.now()}-${Math.random().toString(16).slice(2,6)}`;nodes.value.push({id,name:type==='AND'||type==='OR'?`${type}逻辑门`:'新故障事件',type,x:80+(nodes.value.length%4)*190,y:70+Math.floor(nodes.value.length/4)*130})}function removeNode(id){nodes.value=nodes.value.filter(n=>n.id!==id);edges.value=edges.value.filter(e=>e.source!==id&&e.target!==id)}function addEdge(){const{source,target}=edgeForm.value;if(!source||!target)return ElMessage.warning('请选择父节点和子节点');if(source===target)return ElMessage.warning('不能连接自身');if(edges.value.some(e=>e.source===source&&e.target===target))return ElMessage.warning('连线已存在');edges.value.push({source,target});edgeForm.value={source:'',target:''}}function autoLayout(){const incoming=Object.fromEntries(nodes.value.map(n=>[n.id,0]));edges.value.forEach(e=>incoming[e.target]=(incoming[e.target]||0)+1);let level=nodes.value.filter(n=>!incoming[n.id]).map(n=>n.id),seen=new Set(),depth=0;while(level.length){level.forEach((id,i)=>{const n=nodes.value.find(x=>x.id===id);if(n){n.x=70+i*190;n.y=45+depth*135}seen.add(id)});level=[...new Set(edges.value.filter(e=>level.includes(e.source)&&!seen.has(e.target)).map(e=>e.target))];depth++}nodes.value.filter(n=>!seen.has(n.id)).forEach((n,i)=>{n.x=70+i*190;n.y=45+depth*135})}let dragging=null;function startDrag(event,node){dragging={node,dx:event.clientX-node.x,dy:event.clientY-node.y};window.addEventListener('pointermove',drag);window.addEventListener('pointerup',stopDrag)}function drag(event){if(!dragging)return;const rect=canvas.value.getBoundingClientRect();dragging.node.x=Math.max(0,Math.min(canvasWidth-145,event.clientX-rect.left-(dragging.dx-dragging.node.x)));dragging.node.y=Math.max(0,Math.min(canvasHeight-70,event.clientY-rect.top-(dragging.dy-dragging.node.y)))}function stopDrag(){dragging=null;window.removeEventListener('pointermove',drag);window.removeEventListener('pointerup',stopDrag)}async function load(){const r=await fetch('/api/v1/knowledge/fault-trees/');const data=await r.json();const t=data[0];if(t){treeId.value=t.id;treeName.value=t.name;version.value=t.version;nodes.value=(t.graph?.nodes||[]).map((n,i)=>({...n,x:Number(n.x??70+(i%4)*190),y:Number(n.y??45+Math.floor(i/4)*135)}));edges.value=t.graph?.edges||[]}if(!nodes.value.length){nodes.value=[{id:'top-1',name:'运载器任务失效',type:'top',x:360,y:40},{id:'or-1',name:'任一关键分系统失效',type:'OR',x:360,y:175},{id:'power-1',name:'动力系统失效',type:'event',x:170,y:310},{id:'electric-1',name:'电源系统失效',type:'event',x:550,y:310}];edges.value=[{source:'top-1',target:'or-1'},{source:'or-1',target:'power-1'},{source:'or-1',target:'electric-1'}]}}async function save(){const body={name:treeName.value,graph:{nodes:nodes.value,edges:edges.value,layout:{width:canvasWidth,height:canvasHeight}}};const url=treeId.value?`/api/v1/knowledge/fault-trees/${treeId.value}/`:'/api/v1/knowledge/fault-trees/';const r=await fetch(url,{method:treeId.value?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const j=await r.json();if(!r.ok)return ElMessage.error(j.graph||j.detail||'保存失败');treeId.value=j.id;version.value=j.version;ElMessage.success('故障树节点、逻辑门和边已保存')}onMounted(load);onUnmounted(stopDrag)</script>
<style scoped>.page{max-width:1500px}.head,.title{display:flex;justify-content:space-between;align-items:flex-start}.head{margin-bottom:18px}.head span{font-size:12px;color:#1677ff;letter-spacing:1px}.head h2{margin:8px 0}.head p,.title span{color:#718198}.layout{display:grid;grid-template-columns:500px 1fr;gap:16px}.buttons{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:12px}.edge-add{display:flex;align-items:center;gap:8px;margin-bottom:10px}.edge-add .el-select{flex:1}.canvas{height:650px;position:relative;overflow:auto;background-image:linear-gradient(#e8edf3 1px,transparent 1px),linear-gradient(90deg,#e8edf3 1px,transparent 1px);background-size:20px 20px}.canvas svg{position:absolute;width:900px;height:650px;pointer-events:none}.node{position:absolute;width:140px;min-height:58px;box-sizing:border-box;padding:11px;border:2px solid #6198c7;border-radius:9px;background:white;text-align:center;cursor:move;user-select:none;box-shadow:0 3px 10px #1d4b7520}.node small{display:block;color:#75869a;font-size:11px;margin-top:4px}.node.top{background:#fff0f0;border-color:#d85a5a}.node.basic{border-radius:25px;background:#f1f8ff}.node.AND,.node.OR{width:86px;height:64px;border-radius:50%;background:#fff8e6;border-color:#d59b28;padding-top:19px;font-weight:700}.gate{font-size:16px}@media(max-width:1050px){.layout{grid-template-columns:1fr}.editor{order:2}}</style>
